def _to_index_keys(index: Any, /, *, nested: bool) -> Any:
    """Translate `index` into the key(s) understood by `set_index`.

    `index` may be:
      - a Narwhals `Series` (or a sequence of them, to build a multi-index),
      - something index-like, such as the output of `maybe_get_index`
        (e.g. a pandas `Index`), or a numpy array,
      - a plain sequence of index values, e.g. `[0, 1, 2]`.

    `nested` controls how a plain sequence of values is returned: `pandas` interprets
    a flat list as *column names*, so it needs to be nested when used with
    `DataFrame.set_index`, whereas `Series.set_axis` wants it flat.
    """
    from narwhals.series import Series
    from narwhals.translate import to_native

    if isinstance(index, Series):
        return to_native(index, pass_through=True)
    if not isinstance(index, Iterable) or isinstance(index, (str, bytes)):
        return to_native(index, pass_through=True)
    items = list(index)
    if any(isinstance(item, Series) for item in items):
        # A sequence of Narwhals Series, e.g. `index=[s0, s1]`.
        return [to_native(item, pass_through=True) for item in items]
    if isinstance(index, (list, tuple)) or _is_sequence_of_values(items):
        # A sequence of index *values*, e.g. `index=[1, 2, 0]`.
        return [items] if nested else items
    # Anything else index-like, e.g. a pandas `Index` or a numpy array.
    return to_native(index, pass_through=True)


